    def __repr__(self):
        cn = self.__class__.__name__
        parts = ['spec=%r' % self.spec]
        if self.default is not RAISE:
            parts.append('default=%r' % self.default)
        if self.validators:
            parts.append('validators=%r' % self.validators)
        if self.instance_of:
            parts.append('instance_of=%r' % self.instance_of)
        if self.types:
            parts.append('types=%r' % self.types)
        if self.vals:
            parts.append('vals=%r' % self.vals)
        return '%s(%s)' % (cn, ', '.join(parts))


